/**
 * A1 placeholder map stamps (arena, trainer, rest stop) and badge art, generated by code
 * in the same paper-and-ink look as the creature markers. Original shapes only.
 */
const INK = '#3b2a20';
const PAPER = '#fbf4e6';

export type StampKind = 'arena' | 'trainer' | 'restStop';
export const STAMP_KINDS: StampKind[] = ['arena', 'trainer', 'restStop'];

const STAMP_COLOUR: Record<StampKind, string> = {
  arena: '#c8553d',
  trainer: '#3d6fa8',
  restStop: '#4f9a63',
};

/** Postage-stamp edge: a rounded square with scalloped perforation dots. */
function stampFrame(colour: string): string {
  const dots: string[] = [];
  for (let i = 0; i < 7; i++) {
    const p = 8 + i * 8;
    dots.push(
      `<circle cx="${p}" cy="4" r="2.6"/>`,
      `<circle cx="${p}" cy="60" r="2.6"/>`,
      `<circle cx="4" cy="${p}" r="2.6"/>`,
      `<circle cx="60" cy="${p}" r="2.6"/>`,
    );
  }
  return [
    `<rect x="4" y="4" width="56" height="56" rx="5" fill="${PAPER}" stroke="${INK}" stroke-width="2.5"/>`,
    `<g fill="#f3ead6">${dots.join('')}</g>`,
    `<rect x="10" y="10" width="44" height="44" rx="3" fill="${colour}" stroke="${INK}" stroke-width="2"/>`,
  ].join('');
}

const ICON: Record<StampKind, string> = {
  // A crown-topped gate: the arena.
  arena: [
    `<path d="M18 46 V28 H46 V46" fill="${PAPER}" stroke="${INK}" stroke-width="2.4" stroke-linejoin="round"/>`,
    `<path d="M26 46 V36 a6 6 0 0 1 12 0 V46" fill="${INK}"/>`,
    `<path d="M18 28 L22 18 L28 24 L32 15 L36 24 L42 18 L46 28 Z" fill="#f2c14e" stroke="${INK}" stroke-width="2.2" stroke-linejoin="round"/>`,
  ].join(''),
  // A walking figure with a cap: a route trainer.
  trainer: [
    `<circle cx="32" cy="22" r="6" fill="${PAPER}" stroke="${INK}" stroke-width="2.2"/>`,
    `<path d="M25 20 Q32 12 39 20 Z" fill="#f2c14e" stroke="${INK}" stroke-width="2"/>`,
    `<path d="M24 46 L28 31 H36 L40 46" fill="${PAPER}" stroke="${INK}" stroke-width="2.4" stroke-linejoin="round"/>`,
    `<path d="M28 33 L22 39 M36 33 L42 38" stroke="${INK}" stroke-width="2.4" stroke-linecap="round"/>`,
  ].join(''),
  // A bench under a leaf: the rest stop.
  restStop: [
    `<path d="M32 14 C40 18 44 26 40 32 C36 36 28 36 24 32 C20 26 24 18 32 14Z" fill="#b9da9c" stroke="${INK}" stroke-width="2.2"/>`,
    `<path d="M32 18 V33" stroke="${INK}" stroke-width="1.8"/>`,
    `<path d="M18 40 H46 M20 46 V40 M44 46 V40 M18 36 H46" stroke="${PAPER}" stroke-width="3" stroke-linecap="round"/>`,
    `<path d="M18 40 H46 M20 46 V40 M44 46 V40 M18 36 H46" stroke="${INK}" stroke-width="1.2" stroke-linecap="round" fill="none"/>`,
  ].join(''),
};

/** A POI stamp (64×64 viewBox). `done` draws a "beaten" tick. */
export function stampSvg(kind: StampKind, done = false): string {
  return [
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" role="img">`,
    stampFrame(done ? '#a99c8a' : STAMP_COLOUR[kind]),
    ICON[kind],
    done
      ? `<circle cx="50" cy="50" r="9" fill="${PAPER}" stroke="${INK}" stroke-width="2"/><path d="M45 50 l4 4 l7 -8" fill="none" stroke="#2f7a45" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>`
      : '',
    `</svg>`,
  ].join('');
}

const BADGE_COLOUR = [
  '#c8553d',
  '#3d8fb8',
  '#9b6bc2',
  '#8a8f98',
  '#2f6f8f',
  '#b07a3a',
  '#5a9a4f',
  '#d39a2f',
];

/** Badge art for arena 1–8 (64×64): a rosette with the arena number in pips. */
export function badgeSvg(arena: number, earned = true): string {
  const colour = earned ? BADGE_COLOUR[(arena - 1) % 8]! : '#d8ccb8';
  const petals: string[] = [];
  for (let i = 0; i < 12; i++) {
    const a = (i / 12) * Math.PI * 2;
    const x = 32 + Math.cos(a) * 22;
    const y = 32 + Math.sin(a) * 22;
    petals.push(`<circle cx="${x.toFixed(2)}" cy="${y.toFixed(2)}" r="7"/>`);
  }
  const pips: string[] = [];
  for (let i = 0; i < arena; i++) {
    const a = (i / arena) * Math.PI * 2 - Math.PI / 2;
    const r = arena === 1 ? 0 : 8;
    pips.push(
      `<circle cx="${(32 + Math.cos(a) * r).toFixed(2)}" cy="${(32 + Math.sin(a) * r).toFixed(2)}" r="3.2"/>`,
    );
  }
  return [
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" role="img">`,
    `<g fill="${colour}" stroke="${INK}" stroke-width="2">${petals.join('')}</g>`,
    `<circle cx="32" cy="32" r="19" fill="${colour}" stroke="${INK}" stroke-width="2.4"/>`,
    `<circle cx="32" cy="32" r="14" fill="${PAPER}" stroke="${INK}" stroke-width="2"/>`,
    `<g fill="${earned ? INK : '#b5a891'}">${pips.join('')}</g>`,
    `</svg>`,
  ].join('');
}
